ValidationRule.errorConditionFormula:
OR(
  AND(
    NOT(ISBLANK(Valor_Advertencia__c)),
    NOT(ISBLANK(Valor_Critico__c)),
    OR(
      AND(
        OR(ISPICKVAL(Operador_Comparacion__c, "MAYOR_QUE"), ISPICKVAL(Operador_Comparacion__c, "MAYOR_O_IGUAL")),
        Valor_Critico__c <= Valor_Advertencia__c
      ),
      AND(
        OR(ISPICKVAL(Operador_Comparacion__c, "MENOR_QUE"), ISPICKVAL(Operador_Comparacion__c, "MENOR_O_IGUAL")),
        Valor_Critico__c >= Valor_Advertencia__c
      )
    )
  ),
  AND(
    NOT(ISBLANK(Valor_Invalido__c)),
    NOT(ISBLANK(Valor_Critico__c)),
    OR(
      AND(
        OR(ISPICKVAL(Operador_Comparacion__c, "MAYOR_QUE"), ISPICKVAL(Operador_Comparacion__c, "MAYOR_O_IGUAL")),
        Valor_Invalido__c <= Valor_Critico__c
      ),
      AND(
        OR(ISPICKVAL(Operador_Comparacion__c, "MENOR_QUE"), ISPICKVAL(Operador_Comparacion__c, "MENOR_O_IGUAL")),
        Valor_Invalido__c >= Valor_Critico__c
      )
    )
  )
)
